def transform(grid):
    g=[row[:] for row in grid]
    markers=[(r,c) for r,row in enumerate(g) for c,v in enumerate(row) if v not in (0,1)]
    # The colored example object defines the arrangement to find in the zero cells.
    mr=min(r for r,c in markers); mc=min(c for r,c in markers)
    shape={(r-mr,c-mc) for r,c in markers}
    # In these puzzles the repeated objects are occurrences on the zero-valued field.
    h=len(g); w=len(g[0])
    sh=max(r for r,c in shape)+1; sw=max(c for r,c in shape)+1
    color=g[mr][mc]
    for r in range(h-sh+1):
        for c in range(w-sw+1):
            if (r,c)==(mr,mc):
                continue
            if all(g[r+dr][c+dc]==0 for dr,dc in shape):
                for dr,dc in shape:
                    g[r+dr][c+dc]=color
    return g
