def transform(grid):
    from collections import Counter
    original=[row[:] for row in grid]
    result=[row[:] for row in grid]
    counts=Counter(value for row in original for value in row)
    marker_color=min(counts, key=counts.get)
    markers=[(r,c) for r,row in enumerate(original) for c,value in enumerate(row) if value==marker_color]
    top=min(r for r,_ in markers); left=min(c for _,c in markers)
    shape={(r-top,c-left) for r,c in markers}
    sh=max(r for r,_ in shape)+1; sw=max(c for _,c in shape)+1
    for r in range(len(original)-sh+1):
        for c in range(len(original[0])-sw+1):
            if (r,c)==(top,left): continue
            if all(original[r+dr][c+dc]==0 for dr,dc in shape):
                for dr,dc in shape: result[r+dr][c+dc]=marker_color
    return result
